arguments.command:
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
mkdir -p notes
cat > notes/PRC-412.md <<'EOF'
# PRC-412: bin/price 999 prints 900 (expected 899)
原因: f02b252 "tidy up rounding" が切り捨て `$1*90/100` を切り上げ `($1*90+99)/100` に変えた。
同じ式が bin/price, bin/quote, lib/invoice.sh の 3 箇所にあり、全て同じ退行。
対応: 3 箇所とも `$1 * 90 / 100`（切り捨て）に戻し、999 のテストを追加。
EOF
bash scripts/verify.sh && echo OK; git add -A; git commit -qm "PRC-412: restore round-down for member price (price/quote/invoice)

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>"; git log --oneline | head -1

